const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for products with 'mouse' or 'wireless' in the name
const products = db.prepare(\"SELECT * FROM products WHERE LOWER(name) LIKE '%mouse%' OR LOWER(name) LIKE '%wireless%'\").all();
console.log('Mouse/Wireless products:', JSON.stringify(products, null, 2));
"
